    15→package org.pitest.classinfo;
    16→
    17→import java.math.BigInteger;
    18→import java.util.Optional;
    19→
    20→/**
    21→ * Captures information about a class, its position within a hierarchy. Changes to
    22→ * a class between runs are tracked by calculating the hash of its bytecode and the
    23→ * bytecode of classes it has a strong relationship to.
    24→ */
    25→public final class ClassInfo {
    26→
    27→  private final ClassIdentifier        id;
    28→  private final ClassPointer           outerClass;
    29→  private final ClassPointer           superClass;
    30→
    31→  public ClassInfo(ClassPointer superClass, ClassPointer outerClass, ClassInfoBuilder builder) {
    32→    this.superClass = superClass;
    33→    this.outerClass = outerClass;
    34→    this.id = builder.id;
    35→  }
    36→  public ClassIdentifier getId() {
    37→    return this.id;
    38→  }
    39→
    40→  public ClassName getName() {
    41→    return this.id.getName();
    42→  }
    43→
    44→  public Optional<ClassInfo> getOuterClass() {
    45→    return this.outerClass.fetch();
    46→  }
    47→
    48→  public Optional<ClassInfo> getSuperClass() {
    49→    return getParent();
    50→  }
    51→
    52→  public boolean descendsFrom(final Class<?> clazz) {
    53→    return descendsFrom(ClassName.fromClass(clazz));
    54→  }
    55→
    56→  public HierarchicalClassId getHierarchicalId() {
    57→    return new HierarchicalClassId(this.id, getDeepHash());
    58→  }
    59→
    60→  public BigInteger getDeepHash() {
    61→    BigInteger hash = getHash();
    62→    final Optional<ClassInfo> parent = getParent();
    63→    if (parent.isPresent()) {
    64→      hash = hash.add(parent.get().getHash());
    65→    }
    66→    final Optional<ClassInfo> outer = getOuterClass();
    67→    if (outer.isPresent()) {
    68→      hash = hash.add(outer.get().getHash());
    69→    }
    70→    return hash;
    71→  }
    72→
    73→  public BigInteger getHash() {
    74→    return BigInteger.valueOf(this.id.getHash());
    75→  }
    76→
    77→  private Optional<ClassInfo> getParent() {
    78→    if (this.superClass == null) {
    79→      return Optional.empty();
    80→    }
